/* Four-domain executive intelligence board: data comes from the four local databases. */
(() => {
  const board = document.getElementById("intelligenceBoard");
  const grid = document.getElementById("intelligenceDomainGrid");
  const rail = document.getElementById("intelligenceRelationRail");
  const method = document.getElementById("intelligenceMethod");
  const backdrop = document.getElementById("intelligenceDrawerBackdrop");
  const drawer = document.getElementById("intelligenceDrawer");
  const drawerTitle = document.getElementById("intelligenceDrawerTitle");
  const drawerKicker = document.getElementById("intelligenceDrawerKicker");
  const drawerBody = document.getElementById("intelligenceDrawerBody");
  const closeButton = document.getElementById("intelligenceDrawerClose");
  if (!board || !grid || !rail || !backdrop || !drawer || !drawerBody) return;

  const domainLabels = {
    local: "本地竞对",
    international: "国际竞对",
    cloud: "云厂商",
    macro: "宏观政策",
  };
  let payload = null;
  let lastFocus = null;
  let pushedDrawerState = false;
  const selectedEntityByDomain = new Map();
  const selectedFocusByDomain = new Map();
  const manualFocusPauseUntil = new Map();
  let focusRotationCursor = 0;
  let focusRotationTimer = null;
  let payloadSignature = "";

  function safe(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function formatValue(value) {
    if (value == null || value === "") return "-";
    if (typeof value === "number") {
      return new Intl.NumberFormat("zh-HK", { maximumFractionDigits: 2 }).format(value);
    }
    return safe(value);
  }

  function renderScrollingLabel(value) {
    const label = String(value == null ? "" : value);
    return `
      <span class="intelligence-scroll-label" data-intelligence-scroll-label>
        <span class="intelligence-scroll-label-static">${safe(label)}</span>
        <span class="intelligence-scroll-label-track" aria-hidden="true">${safe(label)}</span>
      </span>
    `;
  }

  function measureScrollingLabels(scope = grid) {
    window.requestAnimationFrame(() => {
      scope.querySelectorAll("[data-intelligence-scroll-label]").forEach((label) => {
        const track = label.querySelector(".intelligence-scroll-label-track");
        if (!track) return;
        label.classList.remove("is-overflowing");
        label.style.removeProperty("--label-scroll-distance");
        label.style.removeProperty("--label-scroll-duration");
        const distance = Math.ceil(track.scrollWidth - label.clientWidth);
        if (distance <= 2) return;
        label.style.setProperty("--label-scroll-distance", `${distance}px`);
        label.style.setProperty("--label-scroll-duration", `${Math.min(6, Math.max(1.8, distance / 32)).toFixed(2)}s`);
        label.classList.add("is-overflowing");
      });
    });
  }

  function domainById(id) {
    return payload?.domains?.find((domain) => domain.id === id) || null;
  }

  function relatedEdges(id) {
    return (payload?.relations || []).filter((item) => item.from === id || item.to === id);
  }

  function domainFocuses(domain) {
    if (Array.isArray(domain?.focuses) && domain.focuses.length) return domain.focuses;
    return [{
      id: "overview",
      label: "重点概览",
      visual: "rows",
      metric: domain?.metric || {},
      context: domain?.context || "",
      insight: domain?.insight || "",
      items: Array.isArray(domain?.entities) ? domain.entities : [],
    }];
  }

  function selectedFocusIndex(domain) {
    const focuses = domainFocuses(domain);
    const selected = Number(selectedFocusByDomain.get(domain.id) || 0);
    return Math.max(0, Math.min(selected, Math.max(0, focuses.length - 1)));
  }

  function focusItems(domain, focus) {
    if (Array.isArray(focus?.items)) return focus.items;
    return Array.isArray(domain?.entities) ? domain.entities : [];
  }

  function selectedEntityIndex(domain, focus) {
    const items = focusItems(domain, focus);
    const selectedName = selectedEntityByDomain.get(domain?.id);
    if (!selectedName) return -1;
    return items.findIndex((item) => item.name === selectedName);
  }

  function renderEntityComponents(entity) {
    const components = Array.isArray(entity?.components) ? entity.components : [];
    if (!components.length) return "";
    const total = Number(entity.component_count) || components.length;
    const recordCount = Number(entity.record_count) || 0;
    const countLabel = recordCount && recordCount !== total
      ? `${total} 个唯一项 · ${recordCount} 条记录`
      : `${total} 项`;
    return `
      <section class="intelligence-entity-components" aria-label="具体包含">
        <header><span>具体包含</span><small>${safe(countLabel)}</small></header>
        <ul>${components.slice(0, 10).map((component) => `
          <li>
            <span>${safe(component.label)}</span>
            ${component.value == null ? "" : `<strong>${formatValue(component.value)}<i>${safe(component.unit)}</i></strong>`}
          </li>
        `).join("")}</ul>
      </section>
    `;
  }

  function renderEntityFocus(domain, entity, index, focus, items) {
    if (!entity) {
      const aiAnalysis = focus.ai_summary?.analysis || domain.ai_summary?.analysis;
      const detailId = `intelligence-detail-${String(domain.id)}-${String(focus.id)}-overview`.replace(/[^a-zA-Z0-9_-]/g, "-");
      return `
        <div class="intelligence-entity-focus is-overview">
          <span class="ai-insight-label">
            <svg class="ai-insight-mark" viewBox="0 0 18 18" aria-hidden="true">
              <path d="M8.2 1.6c.35 3.48 2.72 5.85 6.2 6.2-3.48.35-5.85 2.72-6.2 6.2C7.85 10.52 5.48 8.15 2 7.8c3.48-.35 5.85-2.72 6.2-6.2Z"></path>
              <path d="M14.5 1.7v3.2M12.9 3.3h3.2"></path>
            </svg>
            AI 洞察
          </span>
          <strong>${safe(focus.metric?.label || domain.metric?.label || domain.title)}</strong>
          <div id="${safe(detailId)}" class="intelligence-entity-detail-body" data-intelligence-detail-body>
            <p>${safe(aiAnalysis || focus.insight || domain.insight || "暂无综合结论")}</p>
          </div>
        </div>
      `;
    }
    const source = /^https?:\/\//i.test(String(entity.source_url || ""))
      ? `<a href="${safe(entity.source_url)}" target="_self">来源<span aria-hidden="true">↗</span></a>`
      : "";
    const detailId = `intelligence-detail-${String(domain.id)}-${String(focus.id)}-${index}`.replace(/[^a-zA-Z0-9_-]/g, "-");
    const entityAnalysis = entity.ai_summary?.analysis || entity.analysis || focus.insight || entity.detail || "暂无分析结论";
    return `
      <div class="intelligence-entity-focus">
        <span>${safe(entity.name)}</span>
        <strong>${formatValue(entity.value)}<i>${safe(entity.unit)}</i></strong>
        <div id="${safe(detailId)}" class="intelligence-entity-detail-body" data-intelligence-detail-body>
          ${renderEntityComponents(entity)}
          <p>${safe(entityAnalysis)}</p>
        </div>
        <div class="intelligence-entity-actions">
          ${source}
        </div>
      </div>
    `;
  }

  function renderFocusTabs(domain, focuses, selectedIndex) {
    return `
      <div class="intelligence-focus-tabs" role="tablist" aria-label="${safe(domain.title)}关注点">
        ${focuses.map((item, index) => `
          <button type="button" role="tab" aria-selected="${index === selectedIndex ? "true" : "false"}"
            class="${index === selectedIndex ? "is-active" : ""}"
            data-intelligence-focus="${index}" data-intelligence-domain-id="${safe(domain.id)}"
            title="切换到${safe(item.label)}">${safe(item.label)}</button>
        `).join("")}
      </div>
    `;
  }

  function patchIntelligenceNode(current, next) {
    if (current.isEqualNode(next)) return current;
    if (current.nodeType !== next.nodeType || current.nodeName !== next.nodeName) {
      const replacement = next.cloneNode(true);
      current.replaceWith(replacement);
      return replacement;
    }
    if (current.nodeType === Node.TEXT_NODE || current.nodeType === Node.COMMENT_NODE) {
      if (current.nodeValue !== next.nodeValue) current.nodeValue = next.nodeValue;
      return current;
    }

    Array.from(current.attributes).forEach((attribute) => {
      if (!next.hasAttribute(attribute.name)) current.removeAttribute(attribute.name);
    });
    Array.from(next.attributes).forEach((attribute) => {
      if (current.getAttribute(attribute.name) !== attribute.value) {
        current.setAttribute(attribute.name, attribute.value);
      }
    });

    const currentChildren = Array.from(current.childNodes);
    const nextChildren = Array.from(next.childNodes);
    nextChildren.forEach((nextChild, index) => {
      const currentChild = currentChildren[index];
      if (currentChild) patchIntelligenceNode(currentChild, nextChild);
      else current.appendChild(nextChild.cloneNode(true));
    });
    while (current.childNodes.length > nextChildren.length) {
      current.lastChild.remove();
    }
    return current;
  }

  function elementFromMarkup(markup) {
    const template = document.createElement("template");
    template.innerHTML = markup.trim();
    return template.content.firstElementChild;
  }

  function patchElementList(container, markup) {
    const template = document.createElement("template");
    template.innerHTML = markup;
    const nextElements = Array.from(template.content.children);
    const currentElements = Array.from(container.children);
    nextElements.forEach((nextElement, index) => {
      const currentElement = currentElements[index];
      if (currentElement) patchIntelligenceNode(currentElement, nextElement);
      else container.appendChild(nextElement.cloneNode(true));
    });
    Array.from(container.children).slice(nextElements.length).forEach((element) => element.remove());
  }

  function renderRail(relations) {
    const markup = relations.slice(0, 4).map((relation, index) => `
      <button type="button" class="intelligence-relation ${relation.origin === "ai" ? "is-ai-discovery" : ""}"
        data-relation-domain="${safe(relation.from)}" style="--relation-index:${index}"
        title="${safe(relation.detail || relation.title)}" aria-label="发现${index + 1}：${safe(relation.title)}">
        <em>${String(index + 1).padStart(2, "0")}</em>
        <span>${safe(domainLabels[relation.from] || relation.from)} · ${safe(domainLabels[relation.to] || relation.to)}</span>
        <strong>${safe(relation.title)}</strong>
        <small>${safe(relation.origin === "ai" ? "AI 研判" : relation.kind)}</small>
      </button>
    `).join("");
    patchElementList(rail, markup);
  }

  function renderDomainVisual(domain, items, selectedIndex, focus) {
    const maxValue = Math.max(...items.map((item) => Math.abs(Number(item.value) || 0)), 1);
    const visual = focus?.visual || "rows";
    const entityAttributes = (item, index) => `
      role="button" tabindex="0" data-intelligence-entity="${index}"
      data-intelligence-domain-id="${safe(domain.id)}"
      aria-pressed="${index === selectedIndex ? "true" : "false"}"
      aria-label="${index === selectedIndex ? "取消选择并返回AI洞察" : "查看个体分析"}：${safe(item.name)}"`;

    if (visual === "network") {
      const points = items.map((item, index) => ({
        x: items.length <= 1 ? 261 : 42 + index * (438 / (items.length - 1)),
        y: index % 2 ? 70 : 28,
      }));
      const linkPairs = items.flatMap((item, index) => [
        index + 1 < items.length ? [index, index + 1] : null,
        index + 2 < items.length ? [index, index + 2] : null,
      ]).filter(Boolean);
      const links = linkPairs.map(([from, to], index) => `
        <line x1="${points[from].x}" y1="${points[from].y}" x2="${points[to].x}" y2="${points[to].y}" style="--link-index:${index}" />
      `).join("");
      const nodes = items.map((item, index) => {
        const point = points[index];
        const radius = 6 + Math.abs(Number(item.value) || 0) / maxValue * 7;
        return `
          <g ${entityAttributes(item, index)} class="intelligence-viz-entity ${index === selectedIndex ? "is-selected" : ""}">
            <circle cx="${point.x}" cy="${point.y}" r="${radius.toFixed(1)}" />
            <text x="${point.x}" y="${point.y + 25}" text-anchor="middle">${safe(item.name)}</text>
            <text class="viz-value" x="${point.x}" y="${point.y + 36}" text-anchor="middle">${formatValue(item.value)}${safe(item.unit)}</text>
          </g>
        `;
      }).join("");
      return `<div class="intelligence-viz intelligence-viz-network" aria-label="${safe(focus.label)}关系图"><svg viewBox="0 0 522 112" role="img">${links}${nodes}</svg></div>`;
    }

    if (visual === "diverging") {
      return `<ul class="intelligence-viz intelligence-viz-diverging" aria-label="${safe(focus.label)}正负比较">${items.map((item, index) => {
        const numeric = Number(item.value) || 0;
        const size = Math.max(3, Math.abs(numeric) / maxValue * 48);
        return `
          <li ${entityAttributes(item, index)} class="intelligence-viz-entity ${numeric < 0 ? "is-negative" : "is-positive"} ${item.value == null ? "is-missing" : ""} ${index === selectedIndex ? "is-selected" : ""}">
            <span>${renderScrollingLabel(item.name)}</span>
            <i><b style="--viz-size:${size.toFixed(2)}%"></b></i>
            <strong>${formatValue(item.value)}${safe(item.unit)}</strong>
          </li>
        `;
      }).join("")}</ul>`;
    }

    if (visual === "columns") {
      return `<div class="intelligence-viz intelligence-viz-columns" aria-label="${safe(focus.label)}柱列比较">${items.map((item, index) => {
        const height = Math.max(12, Math.abs(Number(item.value) || 0) / maxValue * 100);
        return `
          <div ${entityAttributes(item, index)} class="intelligence-viz-entity ${Number(item.value) < 0 ? "is-negative" : ""} ${index === selectedIndex ? "is-selected" : ""}">
            <strong>${formatValue(item.value)}${safe(item.unit)}</strong>
            <i><b style="--column-height:${height.toFixed(2)}%"></b></i>
            <span>${renderScrollingLabel(item.name)}</span>
          </div>
        `;
      }).join("")}</div>`;
    }

    if (visual === "ranges") {
      const lows = items.map((item) => Number(item.low)).filter(Number.isFinite);
      const highs = items.map((item) => Number(item.high)).filter(Number.isFinite);
      const floor = lows.length ? Math.min(...lows) : 0;
      const ceiling = highs.length ? Math.max(...highs) : 1;
      const span = Math.max(ceiling - floor, 1);
      return `<ul class="intelligence-viz intelligence-viz-ranges" aria-label="${safe(focus.label)}区间比较">${items.map((item, index) => {
        const low = Number(item.low);
        const high = Number(item.high);
        const hasRange = Number.isFinite(low) && Number.isFinite(high);
        const left = hasRange ? (low - floor) / span * 100 : 0;
        const width = hasRange ? Math.max(2, (high - low) / span * 100) : 0;
        return `<li ${entityAttributes(item, index)} class="intelligence-viz-entity ${!hasRange ? "is-missing" : ""} ${index === selectedIndex ? "is-selected" : ""}">
          <span>${renderScrollingLabel(item.name)}</span><i>${hasRange ? `<b style="--range-left:${left.toFixed(2)}%;--range-width:${width.toFixed(2)}%"></b>` : "-"}</i>
          <strong>${formatValue(item.value)}<small>${safe(item.unit)}</small></strong>
        </li>`;
      }).join("")}</ul>`;
    }

    if (visual === "trends") {
      return `<ul class="intelligence-viz intelligence-viz-trends" aria-label="${safe(focus.label)}趋势比较">${items.map((item, index) => {
        const points = (Array.isArray(item.trend) ? item.trend : []).filter((point) => Number.isFinite(Number(point.value)));
        const values = points.map((point) => Number(point.value));
        const low = values.length ? Math.min(...values) : 0;
        const high = values.length ? Math.max(...values) : 1;
        const span = Math.max(high - low, 1);
        const coordinates = points.map((point, pointIndex) => {
          const x = points.length <= 1 ? 50 : pointIndex * (100 / (points.length - 1));
          const y = 17 - ((Number(point.value) - low) / span * 14);
          return `${x.toFixed(1)},${y.toFixed(1)}`;
        }).join(" ");
        const nodes = points.map((point, pointIndex) => {
          const x = points.length <= 1 ? 50 : pointIndex * (100 / (points.length - 1));
          const y = 17 - ((Number(point.value) - low) / span * 14);
          return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="1.25"></circle>`;
        }).join("");
        return `<li ${entityAttributes(item, index)} class="intelligence-viz-entity ${item.value == null ? "is-missing" : ""} ${index === selectedIndex ? "is-selected" : ""}">
          <span>${renderScrollingLabel(item.name)}</span>
          <svg viewBox="0 0 100 20" preserveAspectRatio="none" aria-hidden="true">
            <polyline class="trend-depth" points="${coordinates}"></polyline>
            <polyline class="trend-line" points="${coordinates}"></polyline>
            <g class="trend-nodes">${nodes}</g>
          </svg>
          <strong>${formatValue(item.value)}<small>${safe(item.unit)}</small></strong>
        </li>`;
      }).join("")}</ul>`;
    }

    if (visual === "disclosure") {
      return `<ul class="intelligence-viz intelligence-viz-disclosure" aria-label="${safe(focus.label)}明细">${items.map((item, index) => `
        <li ${entityAttributes(item, index)} class="intelligence-viz-entity ${index === selectedIndex ? "is-selected" : ""}">
          <span>${renderScrollingLabel(item.name)}<small>${safe(item.detail)}</small></span>
          <strong>${formatValue(item.value)}<i>${safe(item.unit)}</i></strong>
        </li>`).join("")}</ul>`;
    }

    if (visual === "kpis") return `<div class="intelligence-viz intelligence-viz-kpis" aria-label="${safe(focus.label)}关键指标">${items.map((item, index) => `
      <div ${entityAttributes(item, index)} class="intelligence-viz-entity ${index === selectedIndex ? "is-selected" : ""}" style="--kpi-index:${index}">
        <span>${renderScrollingLabel(item.name)}</span>
        <strong>${formatValue(item.value)}<i>${safe(item.unit)}</i></strong>
        <small>${safe(item.detail)}</small>
      </div>
    `).join("")}</div>`;

    return `<ul class="intelligence-viz intelligence-viz-rows" aria-label="${safe(focus.label)}排序比较">${items.map((item, index) => {
      const width = Math.max(2, Math.abs(Number(item.value) || 0) / maxValue * 100);
      return `<li ${entityAttributes(item, index)} class="intelligence-viz-entity ${item.value == null ? "is-missing" : ""} ${index === selectedIndex ? "is-selected" : ""}">
        <span>${renderScrollingLabel(item.name)}<small>${safe(item.detail)}</small></span>
        <i><b style="--row-width:${width.toFixed(2)}%"></b></i>
        <strong>${formatValue(item.value)}<small>${safe(item.unit)}</small></strong>
      </li>`;
    }).join("")}</ul>`;
  }

  function renderDomainCard(domain) {
    const focuses = domainFocuses(domain);
    const focusIndex = selectedFocusIndex(domain);
    const selectedFocus = focuses[focusIndex];
    const items = focusItems(domain, selectedFocus);
    const entityIndex = selectedEntityIndex(domain, selectedFocus);
    const selectedEntity = items[entityIndex] || null;
    const focusMetric = selectedFocus.metric || domain.metric || {};
    const visual = renderDomainVisual(domain, items, entityIndex, selectedFocus);
    return `
      <article class="intelligence-domain intelligence-domain-${safe(domain.id)}" data-intelligence-domain-id="${safe(domain.id)}" aria-label="${safe(domain.title)}分析">
        <span class="intelligence-domain-index">${safe(domain.index)}</span>
        <span class="intelligence-domain-heading">
          <span>${safe(domain.kicker)}</span>
          <strong>${safe(domain.title)}</strong>
        </span>
        <span class="intelligence-domain-metric">
          <small>${safe(focusMetric.label)}</small>
          <strong>${formatValue(focusMetric.value)}<i>${safe(focusMetric.unit)}</i></strong>
        </span>
        ${renderFocusTabs(domain, focuses, focusIndex)}
        <div class="intelligence-domain-focus-stage">
          ${visual}
          ${renderEntityFocus(domain, selectedEntity, entityIndex, selectedFocus, items)}
        </div>
      </article>
    `;
  }

  function renderDomains(domains) {
    const expectedIds = new Set(domains.map((domain) => String(domain.id)));
    domains.forEach((domain, index) => {
      const selector = `.intelligence-domain[data-intelligence-domain-id="${CSS.escape(domain.id)}"]`;
      let current = grid.querySelector(selector);
      const next = elementFromMarkup(renderDomainCard(domain));
      if (current) current = patchIntelligenceNode(current, next);
      else current = next;
      const position = grid.children[index] || null;
      if (current !== position) grid.insertBefore(current, position);
      measureScrollingLabels(current);
    });
    Array.from(grid.querySelectorAll(".intelligence-domain")).forEach((card) => {
      if (!expectedIds.has(String(card.dataset.intelligenceDomainId || ""))) card.remove();
    });
    Array.from(grid.children).forEach((child) => {
      if (!child.matches(".intelligence-domain")) child.remove();
    });
  }

  function replaceDomainCard(domain, restoreFocus = false) {
    const current = grid.querySelector(`.intelligence-domain[data-intelligence-domain-id="${CSS.escape(domain.id)}"]`);
    if (!current) return;
    const updated = patchIntelligenceNode(current, elementFromMarkup(renderDomainCard(domain)));
    updated.classList.remove("is-content-switching");
    void updated.offsetWidth;
    updated.classList.add("is-content-switching");
    measureScrollingLabels(updated);
    if (restoreFocus) {
      const index = selectedFocusIndex(domain);
      window.requestAnimationFrame(() => {
        grid.querySelector(`[data-intelligence-domain-id="${CSS.escape(domain.id)}"] [role="tab"][data-intelligence-focus="${index}"]`)?.focus();
      });
    }
  }

  function selectEntity(domainId, index, restoreFocus = false, manual = true) {
    const domain = domainById(domainId);
    const focuses = domain ? domainFocuses(domain) : [];
    const focus = domain ? focuses[selectedFocusIndex(domain)] : null;
    const items = focusItems(domain, focus);
    if (!domain || !items[index]) return;
    if (selectedEntityByDomain.get(domainId) === items[index].name) selectedEntityByDomain.delete(domainId);
    else selectedEntityByDomain.set(domainId, items[index].name);
    if (manual) manualFocusPauseUntil.set(domainId, Date.now() + 30000);
    replaceDomainCard(domain, restoreFocus);
  }

  function selectFocus(domainId, index, restoreFocus = false, manual = true) {
    const domain = domainById(domainId);
    const focuses = domain ? domainFocuses(domain) : [];
    if (!domain || !focuses[index]) return;
    selectedFocusByDomain.set(domainId, index);
    selectedEntityByDomain.delete(domainId);
    if (manual) manualFocusPauseUntil.set(domainId, Date.now() + 30000);
    replaceDomainCard(domain, restoreFocus);
  }

  function rotateNextFocus() {
    const domains = Array.isArray(payload?.domains) ? payload.domains : [];
    if (!domains.length || document.hidden) return;
    for (let attempt = 0; attempt < domains.length; attempt += 1) {
      const domain = domains[focusRotationCursor % domains.length];
      focusRotationCursor = (focusRotationCursor + 1) % domains.length;
      const focuses = domainFocuses(domain);
      const card = grid.querySelector(`.intelligence-domain[data-intelligence-domain-id="${CSS.escape(domain.id)}"]`);
      if (focuses.length < 2 || !card) continue;
      if (card.matches(":hover") || card.contains(document.activeElement)) continue;
      if ((manualFocusPauseUntil.get(domain.id) || 0) > Date.now()) continue;
      selectFocus(domain.id, (selectedFocusIndex(domain) + 1) % focuses.length, false, false);
      return;
    }
  }

  function startFocusRotation() {
    if (focusRotationTimer) window.clearInterval(focusRotationTimer);
    focusRotationTimer = window.setInterval(rotateNextFocus, 4200);
  }

  function renderDrawer(domain) {
    const entities = Array.isArray(domain.entities) ? domain.entities : [];
    const maxValue = Math.max(...entities.map((item) => Math.abs(Number(item.value) || 0)), 1);
    const entityRows = entities.map((item) => {
      const width = Math.max(3, Math.abs(Number(item.value) || 0) / maxValue * 100);
      const name = safe(item.name);
      return `
        <li>
          <div><strong>${name}</strong></div>
          <div class="intelligence-entity-value"><i><b style="--bar-width:${width.toFixed(2)}%"></b></i><strong>${formatValue(item.value)} ${safe(item.unit)}</strong></div>
          ${item.source_url ? `<a href="${safe(item.source_url)}" target="_self" aria-label="打开${name}来源">来源<span aria-hidden="true">↗</span></a>` : ""}
        </li>
      `;
    }).join("");
    const domainCrossRelations = relatedEdges(domain.id);
    const crossRelations = domainCrossRelations.map((relation) => {
      const peer = relation.from === domain.id ? relation.to : relation.from;
      return `
        <button type="button" data-intelligence-peer="${safe(peer)}">
          <span>联动 ${safe(domainLabels[peer] || peer)}</span>
          <strong>${safe(relation.title)}</strong>
        </button>
      `;
    }).join("");
    const sources = (domain.sources || []).map((source) => `
      <a href="${safe(source.url)}" target="_self">${safe(source.label)}<span aria-hidden="true">↗</span></a>
    `).join("");
    const aiSummary = domain.ai_summary || {};
    const internalRelations = Array.isArray(domain.relations) ? domain.relations : [];
    const conclusionCandidates = [
      internalRelations[0]?.title,
      ...domainCrossRelations.map((relation) => relation.title),
      aiSummary.headline || domain.insight,
    ].filter(Boolean);
    const conclusions = Array.from(new Set(conclusionCandidates)).slice(0, 3);
    const conclusionRows = conclusions.map((text, index) => `
      <li><span>0${index + 1}</span><strong>${safe(text)}</strong></li>
    `).join("");
    const verifiedCount = Array.isArray(domain.ai_analysis) ? domain.ai_analysis.length : 0;
    const sourceCount = Array.isArray(domain.sources) ? domain.sources.length : 0;

    drawerKicker.textContent = `${domain.index} · AI 洞察`;
    drawerTitle.textContent = domain.title;
    drawerBody.innerHTML = `
      <section class="intelligence-detail-lead">
        <span>当前关键结果 · ${safe(domain.metric?.label)}</span>
        <strong>${formatValue(domain.metric?.value)}<i>${safe(domain.metric?.unit)}</i></strong>
        <p>${safe(domain.insight)}</p>
      </section>
      <div class="intelligence-summary-strip" aria-label="综合渠道覆盖">
        <span><strong>${entities.length}</strong>个对象</span>
        <span><strong>${domainCrossRelations.length}</strong>条跨库联动</span>
        <span><strong>${sourceCount}</strong>个来源入口</span>
        <span><strong>${verifiedCount}</strong>项Agent核验</span>
      </div>
      <section class="intelligence-detail-section">
        <h3>领导结论</h3>
        <ol class="intelligence-decision-list">${conclusionRows}</ol>
      </section>
      <section class="intelligence-detail-section">
        <h3>跨渠道联动</h3>
        <div class="intelligence-cross-relations">${crossRelations || "<p>暂无跨库关系</p>"}</div>
      </section>
      <section class="intelligence-detail-section">
        <h3>对象对比</h3>
        <ul class="intelligence-entity-list">${entityRows}</ul>
      </section>
      <section class="intelligence-detail-section intelligence-source-list">
        <h3>来源入口</h3>
        <div>${sources}</div>
      </section>
    `;
  }

  function updateUrl(id, mode) {
    const url = new URL(window.location.href);
    if (id) url.searchParams.set("intelligence", id);
    else url.searchParams.delete("intelligence");
    window.history[mode]({ intelligence: id || null }, "", url);
  }

  function openDrawer(id, push = true) {
    const domain = domainById(id);
    if (!domain) return;
    lastFocus = document.activeElement;
    renderDrawer(domain);
    backdrop.hidden = false;
    document.body.classList.add("intelligence-drawer-open");
    if (push) {
      updateUrl(id, "pushState");
      pushedDrawerState = true;
    }
    window.requestAnimationFrame(() => {
      backdrop.classList.add("is-open");
      drawer.focus();
    });
  }

  function closeDrawer(fromHistory = false) {
    if (backdrop.hidden) return;
    backdrop.classList.remove("is-open");
    document.body.classList.remove("intelligence-drawer-open");
    window.setTimeout(() => { backdrop.hidden = true; }, 180);
    if (!fromHistory) {
      if (pushedDrawerState) window.history.back();
      else updateUrl(null, "replaceState");
    }
    pushedDrawerState = false;
    if (lastFocus?.focus) lastFocus.focus();
  }

  grid.addEventListener("click", (event) => {
    const sourceLink = event.target.closest(".intelligence-entity-actions > a");
    if (sourceLink) {
      event.preventDefault();
      event.stopPropagation();
      window.location.assign(sourceLink.href);
      return;
    }
    const focusTrigger = event.target.closest("[data-intelligence-focus]");
    if (focusTrigger) {
      selectFocus(focusTrigger.dataset.intelligenceDomainId, Number(focusTrigger.dataset.intelligenceFocus), true);
      return;
    }
    const entityTrigger = event.target.closest("[data-intelligence-entity]");
    if (entityTrigger) {
      selectEntity(entityTrigger.dataset.intelligenceDomainId, Number(entityTrigger.dataset.intelligenceEntity));
      return;
    }
  });
  grid.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const entityTrigger = event.target.closest('.intelligence-viz-entity[data-intelligence-entity]');
    if (!entityTrigger) return;
    event.preventDefault();
    selectEntity(entityTrigger.dataset.intelligenceDomainId, Number(entityTrigger.dataset.intelligenceEntity), true);
  });
  rail.addEventListener("click", (event) => {
    const trigger = event.target.closest("[data-relation-domain]");
    if (trigger) openDrawer(trigger.dataset.relationDomain);
  });
  drawerBody.addEventListener("click", (event) => {
    const trigger = event.target.closest("[data-intelligence-peer]");
    if (!trigger) return;
    const peer = trigger.dataset.intelligencePeer;
    const domain = domainById(peer);
    if (!domain) return;
    renderDrawer(domain);
    updateUrl(peer, "replaceState");
    drawer.scrollTo({ top: 0, behavior: "smooth" });
  });
  closeButton.addEventListener("click", () => closeDrawer());
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) closeDrawer();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !backdrop.hidden) closeDrawer();
  });
  window.addEventListener("popstate", () => {
    const id = new URL(window.location.href).searchParams.get("intelligence");
    if (id && domainById(id)) openDrawer(id, false);
    else closeDrawer(true);
  });
  let labelResizeTimer = null;
  window.addEventListener("resize", () => {
    window.clearTimeout(labelResizeTimer);
    labelResizeTimer = window.setTimeout(() => measureScrollingLabels(), 120);
  });

  function refreshIntelligencePayload(initial = false) {
    Promise.resolve({ ok: true, json: () => Promise.resolve(window.CMHK_STATIC_INTELLIGENCE) })
      .then((response) => response.json().then((data) => ({ response, data })))
      .then(({ response, data }) => {
        if (!response.ok || !data.ok) throw new Error(data.error || "四库关系读取失败");
        const signature = JSON.stringify({
          refresh: data.refresh?.completed_at_hkt || data.refresh?.started_at_hkt || "",
          ai: data.ai?.updated_at || "",
          aiSummaries: (data.domains || []).map((domain) => [domain.id, domain.ai_summary, (domain.focuses || []).map((focus) => [focus.id, focus.ai_summary])]),
          discoveries: (data.relations || []).map((relation) => [relation.from, relation.to, relation.title, relation.detail]),
          metrics: (data.domains || []).map((domain) => [domain.id, domain.metric, domain.context]),
        });
        if (!initial && signature === payloadSignature) return;
        payloadSignature = signature;
        payload = data;
        renderRail(data.relations || []);
        renderDomains(data.domains || []);
        if (!focusRotationTimer) startFocusRotation();
        const refreshStatus = data.refresh?.status;
        const refreshTime = String(data.refresh?.completed_at_hkt || data.ai?.updated_at || "").replace("T", " ").slice(0, 19);
        method.textContent = (data.method || "四库同口径对齐")
          + (refreshStatus ? ` · 更新：${refreshStatus}${refreshTime ? ` ${refreshTime}` : ""}` : "");
        const requested = new URL(window.location.href).searchParams.get("intelligence");
        if (requested) openDrawer(requested, false);
      })
      .catch((error) => {
        if (payload) {
          method.textContent = "自动更新暂时失败，继续展示最后可用数据";
          return;
        }
        grid.innerHTML = `<div class="intelligence-loading is-error"><strong>四库关系暂时无法读取</strong><span>${safe(error.message || error)}</span></div>`;
        method.textContent = "保留最后可用数据，等待服务恢复";
      });
  }

  refreshIntelligencePayload(true);
  window.setInterval(() => {}, 60000);
})();



(() => {
  const list = document.getElementById("strategyTickerList");
  const track = list?.querySelector(".strategy-ticker-track");
  if (!list || !track) return;
  let paused = false;
  let offset = 0;
  let last = performance.now();
  const speed = 42;
  const firstSet = Array.from(track.children).filter((item) => !item.classList.contains("strategy-ticker-clone"));
  const loopWidth = () => firstSet.reduce((total, item) => total + item.getBoundingClientRect().width, 0);
  const tick = (now) => {
    const elapsed = Math.min(48, now - last);
    last = now;
    if (!paused) {
      offset -= speed * elapsed / 1000;
      const width = loopWidth();
      if (width > 0 && -offset >= width) offset += width;
      track.style.transform = `translate3d(${offset}px, 0, 0)`;
    }
    requestAnimationFrame(tick);
  };
  ["pointerenter", "focusin", "touchstart"].forEach((eventName) => list.addEventListener(eventName, () => { paused = true; }));
  ["pointerleave", "focusout", "touchend"].forEach((eventName) => list.addEventListener(eventName, () => { paused = false; }));
  requestAnimationFrame(tick);
})();
